import { setTimeout as sleep } from 'node:timers/promises';
import { pathToFileURL } from 'node:url';
const [root, sha] = process.argv.slice(2);
const canonical='/home/marsh-office/papercupai-workspace/papercusp';
if (!root?.startsWith('/tmp/pcv/papercusp-lint-as-committed-') || !/^[a-f0-9]{40}$/.test(sha ?? '')) throw Error('exact official immutable root and commit required');
const git=(...args)=>execFileSync('git',args,{cwd:root,encoding:'utf8',timeout:10000}).trim();
if (git('rev-parse','HEAD')!==sha || git('status','--porcelain')) throw Error('immutable source is not pristine at requested commit');
const inputs=JSON.parse(readFileSync('/tmp/egm-e4-containing-source.json','utf8')).inputs;
const mismatch=inputs.filter(x=>git('rev-parse',sha+':'+x.path)!==x.before);
if (mismatch.length) throw Error('original recipe inputs changed: '+mismatch.map(x=>x.path).join(','));
const diagnostics={
 'src/admin-test-runs-reporter.ts':'ae7d873947f39bc6f4107876e141090f57274ceb',
 'src/admin-test-runs-reporter.test.ts':'f1e5807aeca06c5e70c720a34810d93f2fb7312a',
 'src/test-case-runs.integration.test.ts':'b80d0ad1e9ec7b66538d38fefa76aa58fef2d26e'
};
for (const [path,expected] of Object.entries(diagnostics)) {
 const got=execFileSync('git',['rev-parse','HEAD:'+path],{cwd:root+'/libs/test-config',encoding:'utf8',timeout:10000}).trim();
 if(got!==expected)throw Error('diagnostic blob mismatch: '+path);
}
const {resolveScriptPgUrl}=await import(pathToFileURL(canonical+'/scripts/lib/pg-url.mjs').href);
const sink=resolveScriptPgUrl().url;
const require=createRequire(root+'/package.json'), {Client}=require('pg');
const app='egm-p003-7a78-'+Date.now().toString(36);
const base='/tmp/egm-p003-wait-'+app;
const paths={samples:base+'.samples.jsonl',log:base+'.probe.log',status:base+'.status.json'};
const c=new Client({connectionString:sink,application_name:app+'-sampler',connectionTimeoutMillis:3000,statement_timeout:1500,query_timeout:2000});
const query="SELECT clock_timestamp() AS observed_at,pid,state,wait_event_type,wait_event,round(extract(epoch FROM clock_timestamp()-query_start)*1000) AS query_age_ms,pg_blocking_pids(pid) AS blockers,md5(query) AS query_hash,CASE WHEN query ~* '^\\s*INSERT\\s+INTO\\s+harness_shared.test_runs' THEN 'test_runs_insert' WHEN query ~* '^\\s*INSERT\\s+INTO\\s+harness_shared.test_case_runs' THEN 'test_case_runs_insert' ELSE 'other' END AS query_kind FROM pg_stat_activity WHERE application_name=$1 ORDER BY pid LIMIT 20";
let child, fd, exitPromise, done=false, timedOut=false, sampleErrors=0, sampleCount=0;
const hist={}, startedAt=new Date().toISOString();
const record=x=>appendFileSync(paths.samples,JSON.stringify(x)+'\n');
const status=x=>writeFileSync(paths.status,JSON.stringify({schemaVersion:1,app,root,sha,paths,startedAt,sampleCount,sampleErrors,timedOut,...x},null,2));
try {
 await c.connect();
 await c.query('SET default_transaction_read_only=on');
 const own=await c.query('SELECT pid FROM pg_stat_activity WHERE application_name=$1',[app+'-sampler']);
 if(own.rows.length!==1)throw Error('sampler identity was not unique');
 await c.query("EXPLAIN INSERT INTO harness_shared.test_runs(file_path,status) VALUES('egm.wait.preflight.test.ts','pass') RETURNING id,file_path");
 await c.query(query,[app]);
 record({kind:'preflight',at:new Date().toISOString(),app,sha,recipeInputs:inputs.length,diagnosticBlobs:diagnostics});
 const args=JSON.parse(readFileSync('/tmp/egm-e4-mutant-descriptors.json','utf8')).descriptors.metadata;
 const env={...process.env,PGAPPNAME:app,PAPERCUSP_TEST_RUNS_DB_URL:sink,PAPERCUSP_TEST_RUN_WORKSPACE:'papercusp-workspace',PAPERCUSP_TEST_RUN_HARNESS:'papercusp',PAPERCUSP_TEST_RUN_OWNER_ID:'su-7a78cfd7-0fc3-40b7-93b5-edfe202c0c49',PAPERCUSP_TEST_RUN_WORK_ITEM:'WI-6554700010044325',PAPERCUSP_MUTATION_DESCRIPTOR_READER_HEALTH_URL:'http://127.0.0.1:3170/api/health',PAPERCUSP_MUTATION_DESCRIPTOR_READER_REPO:canonical,PAPERCUSP_MUTATION_DESCRIPTOR_EXPORT:'auto',PAPERCUSP_MUTATION_DESCRIPTOR_READER_REQUIRED:'1'};
 fd=openSync(paths.log,'wx');
 child=spawn(process.execPath,['--import','./scripts/lib/committed-source-loader.mjs','--import','tsx','scripts/with-test-pg.mjs','--','bash','scripts/mutation-probe.sh',...args],{cwd:root,env,detached:true,stdio:['ignore',fd,fd]});
 const exit=new Promise(resolve=>{child.once('error',e=>resolve({code:null,signal:null,spawnError:e.message}));child.once('close',(code,signal)=>resolve({code,signal}));}).finally(()=>{done=true;}); exitPromise=exit;
 const deadline=Date.now()+20*60*1000;
 status({phase:'running',childPid:child.pid,deadline});
 while(!done && Date.now()<deadline) {
   const before=Date.now();
   try {
     const r=await c.query(query,[app]); sampleCount++;
     record({kind:'sample',at:new Date().toISOString(),elapsedMs:Date.now()-before,rows:r.rows,possiblyTruncated:r.rows.length===20});
     for(const row of r.rows){const key=[row.query_kind,row.wait_event_type??'none',row.wait_event??'none'].join('/');hist[key]=(hist[key]??0)+1;}
     const blocking=[...new Set(r.rows.flatMap(x=>x.blockers??[]))];
     if(blocking.length) {
       const b=await c.query('SELECT pid,application_name,state,wait_event_type,wait_event,md5(query) AS query_hash FROM pg_stat_activity WHERE pid=ANY($1::integer[])',[blocking]);
       const l=await c.query('SELECT pid,locktype,mode,granted,relation::regclass::text AS relation,transactionid::text FROM pg_locks WHERE pid=ANY($1::integer[]) LIMIT 100',[[...blocking,...r.rows.map(x=>x.pid)]]);
       record({kind:'blocker-detail',at:new Date().toISOString(),blockers:b.rows,locks:l.rows,possiblyTruncated:l.rows.length===100});
     }
   }catch(e){sampleErrors++;record({kind:'sample-error',at:new Date().toISOString(),name:e.name,code:e.code??null});}
   status({phase:'running',childPid:child.pid,waitHistogram:hist});
   await sleep(Math.max(10,750-(Date.now()-before)));
 }
 if(!done){timedOut=true;process.kill(-child.pid,'SIGTERM');await Promise.race([exit,sleep(20000)]);if(!done)process.kill(-child.pid,'SIGKILL');}
 const result=await exit;
 const afterMismatches=inputs.filter(x=>git('hash-object','--',x.path)!==x.before).map(x=>x.path);
 status({phase:'terminal',finishedAt:new Date().toISOString(),result,source17Stable:afterMismatches.length===0,afterMismatches,waitHistogram:hist,cleanupVerification:'Read maintained wrapper terminal cleanup from probe.log; not inferred from exit.'});
 console.log(JSON.stringify({ok:result.code===0&&!timedOut&&afterMismatches.length===0,app,paths,sampleCount,sampleErrors,timedOut,result,waitHistogram:hist}));
 process.exitCode=result.code===0&&!timedOut&&afterMismatches.length===0?0:1;
} catch(e) {
 status({phase:'failed',error:{name:e.name,message:e.message},finishedAt:new Date().toISOString()});
 throw e;
} finally {if(child&&!done){try{process.kill(-child.pid,'SIGTERM');await Promise.race([exitPromise,sleep(20000)]);if(!done)process.kill(-child.pid,'SIGKILL');await exitPromise;}catch{}}if(fd!==undefined)closeSync(fd);await c.end();}

